using System.Linq;
using FourDex.Math4D;
using FourDex.Runtime;
using FourDex.World;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;

namespace FourDex.Tests.EditMode
{
    /// <summary>
    /// The Hall4D scene as authored: a corridor whose barrier exists in one W slice only, so the way past it is to
    /// step kata, walk, and step back ana. This guards what confinement means in 4D, which is what the scene teaches.
    /// </summary>
    /// <remarks>
    /// The scene is generated by <c>Lab4DSceneBuilder.BuildHall</c>, so these tests fail if the openings are changed
    /// without rebuilding it, or if the route is broken by a change to collision.
    /// </remarks>
    public class HallSceneTests
    {
        private const string ScenePath = "Assets/Scenes/Hall4D.unity";

        private Player4D _player;
        private MazeRuntime _maze;
        private float _cell;

        [SetUp]
        public void SetUp()
        {
            EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
            _maze = Object.FindAnyObjectByType<MazeRuntime>();
            _player = Object.FindAnyObjectByType<Player4D>();
            Assert.IsNotNull(_maze, "the scene has a maze");
            Assert.IsNotNull(_player, "the scene has a player");
            _cell = _maze.CellSize;

            // OnEnable does not run in edit mode; install the filter the way it does.
            _player.State.MovementFilter = (from, to) =>
                CellCollision.Resolve(_maze.Maze, _cell, from, to, 0.35f);
        }

        private void Forward() => _player.State.MoveWorld(new Vec4(0f, 0f, _cell, 0f));

        [Test]
        public void ThePlayerStartsAtTheNearEndOfTheCorridor_InTheMiddleSlice()
        {
            Assert.AreEqual(new Cell4D(0, 0, 0, 1), _maze.CurrentCell);
            StringAssert.Contains("+Z", _maze.Describe());
        }

        [Test]
        public void TheCorridorRunsFreelyUpToTheBarrier_AndThenStops()
        {
            Forward();
            Assert.AreEqual(new Cell4D(0, 0, 1, 1), _maze.CurrentCell);
            Forward();
            Assert.AreEqual(new Cell4D(0, 0, 2, 1), _maze.CurrentCell);

            // Walking into the barrier, hard: no tunnelling, and the stop is a wall's clearance short of the face.
            _player.State.MoveWorld(new Vec4(0f, 0f, 10f * _cell, 0f));
            Assert.AreEqual(new Cell4D(0, 0, 2, 1), _maze.CurrentCell);
            Assert.Less(_player.State.Position.Z, 2.5f * _cell);
        }

        [Test]
        public void TheSameBarrierIsSimplyAbsentOneSliceKata()
        {
            // The whole lesson in two assertions: a wall occupies one cell of W, so it confines you only while you
            // share its slice. Sealing a cell in 4D means closing its W faces too, which the boundary here does.
            Assert.IsTrue(_maze.Maze.HasWall(new Cell4D(0, 0, 2, 1), Direction4.PosZ), "the barrier, in the corridor");
            Assert.IsFalse(_maze.Maze.HasWall(new Cell4D(0, 0, 2, 0), Direction4.PosZ), "not there, one slice kata");
        }

        [Test]
        public void TheWayPastTheBarrierIsKataThenForwardThenAna()
        {
            Forward();
            Forward();
            Assert.AreEqual(new Cell4D(0, 0, 2, 1), _maze.CurrentCell);

            _player.State.MoveAnaKata(-_cell);
            Assert.AreEqual(new Cell4D(0, 0, 2, 0), _maze.CurrentCell, "kata into the parallel corridor");

            Forward();
            Forward();
            Assert.AreEqual(new Cell4D(0, 0, 4, 0), _maze.CurrentCell, "past where the barrier was");

            _player.State.MoveAnaKata(_cell);
            Assert.AreEqual(new Cell4D(0, 0, 4, 1), _maze.CurrentCell, "back ana, beyond the barrier");

            Forward();
            Assert.AreEqual(new Cell4D(0, 0, 5, 1), _maze.CurrentCell, "the far end of the corridor");
        }

        [Test]
        public void TheFarEndIsADeadEndIn3D_WithAWayOutAna()
        {
            _player.State.MoveWorld(new Vec4(0f, 0f, 20f * _cell, 0f)); // as far down the corridor as walls allow
            _player.State.MoveAnaKata(-_cell);
            _player.State.MoveWorld(new Vec4(0f, 0f, 20f * _cell, 0f));
            _player.State.MoveAnaKata(_cell);
            _player.State.MoveWorld(new Vec4(0f, 0f, 20f * _cell, 0f));
            Assert.AreEqual(new Cell4D(0, 0, 5, 1), _maze.CurrentCell);

            // Nowhere further in X, Y or Z: back the way you came, or ana.
            foreach (Direction4 direction in Direction4Extensions.All
                         .Where(d => d.Axis() != 3 && d != Direction4.NegZ))
                Assert.IsTrue(_maze.Maze.HasWall(_maze.CurrentCell, direction), $"{direction} is walled");

            _player.State.MoveAnaKata(_cell);
            Assert.AreEqual(new Cell4D(0, 0, 5, 2), _maze.CurrentCell, "the alcove, reachable only through ana");
        }

        [Test]
        public void WallsSpanExactlyOneCellOfW_SoANeighbouringSlicesWallIsAnEcho()
        {
            Object4DBehaviour[] walls = Object.FindObjectsByType<Object4DBehaviour>(FindObjectsSortMode.None)
                .Where(o => o.name.StartsWith("Wall"))
                .ToArray();
            Assert.Greater(walls.Length, 0);
            foreach (Object4DBehaviour wall in walls)
            {
                // A wall across the corridor spans its cell's W and no further, so from the next slice it is a
                // dithered echo you can survey but walk through. A wall across a W face is the thin one: it is what
                // stops you stepping ana, and it is why a cell can be sealed at all.
                bool acrossW = wall.name.EndsWith("PosW") || wall.name.EndsWith("NegW");
                Assert.AreEqual(acrossW ? 0.1f : 0.5f * _cell, wall.AuthoredHalfExtents.W, 1e-4f, wall.name);
            }
        }
    }
}
